import {
  InuSvgTimeline,
  InuSvgTimelineHistogram,
  InuSvgTimelineLine
} from 'inugami-ng/components/inu-svg-timeline';
import {
  BucketTimed,
  BucketTimedLoader,
  InuSelectItem,
  ResourceTimedSelected,
  TimeLineRenderer
} from 'inugami-ng/models'

@Component({
   templateUrl: './inu-svg-timeline.view.html',
   styleUrls  : ['./inu-svg-timeline.view.scss'],
   imports    : [
     InuSvgTimeline
   ]
})
export class MyView {
  // attributes
  loadData    = signal<BucketTimedLoader<number> | undefined>(undefined);
  from        = signal<Date>(new Date('2026-08-06T00:00:00.000+02:00'));
  until       = signal<Date>(new Date('2026-08-06T23:59:00.000+02:00'));
  renderer    = signal<TimeLineRendererBuilder>(() => new InuSvgTimelineHistogram());
  resolution  = signal<number>(250);

  // inject
  http        = inject(HttpClient);

  constructor() {
    this.loadData.set(this.processLoadingData.bind(this));
  }

  private processLoadingData(from: Date,
                             until: Date,
                             resolution: number): Observable<BucketTimed<number>[]> {
    const currentRequest: any = {
      from      : from.getTime(),
      until     : until.getTime(),
      resolution: resolution
    };
    const params              = new HttpParams({fromObject: currentRequest});

    return this.http.get<BucketTimed<number>[]>(`api/svg/timeline`, {params})

  }
}


export interface BucketTimed<T = number> {
  name: string;
  resources: ResourceTimed<T>[];
  tags?: string[];
}


export interface ResourceTimed<T = number> {
  uri: string;
  values: PointTimed<T>[];
  unit: string;
  name?: string;
}


export interface PointTimed<T = number> {
  value: T;
  time: Date;
  meta?: Record<string, string | number | boolean>;
}


export interface MouseEventData{
  altKey: boolean;
  button: number;
  buttons: number;
  clientX: number;
  clientY: number;
  ctrlKey: boolean;
  layerX: number;
  layerY: number;
  metaKey: boolean;
  movementX: number;
  movementY: number;
  offsetX: number;
  offsetY: number;
  pageX: number;
  pageY: number;
  screenX: number;
  screenY: number;
  shiftKey: boolean;
  x: number;
  y: number;
}


export interface ResourceTimedSelected{
  bucket : BucketTimed<number>;
  point : PointTimed<number>;
  event: MouseEventData;
}


export type BucketTimedLoader<T = number> = (from: Date,
                                             until: Date,
                                             resolution: number) => Observable<BucketTimed<T>[]>;


@Component({
   //...
})
export class MyView {
  // attributes
  loadData    = loadData = signal<BucketTimedLoader<number>>((from, until, resolution) => {
    const currentRequest = {
      from: from.getTime(),
      until: until.getTime(),
      resolution: resolution
    };
    const params = new HttpParams({ fromObject: currentRequest });

    return this.http.get<BucketTimed<number>[]>(`api/svg/timeline`, { params });
  });
  //...

  // inject
  http        = inject(HttpClient);
}


export interface TimeLineRendererContext {
  graph: SVGElement;
  height: number;
  width: number;
  resolution: number;
}


export interface TimeLineRenderer {
  init: (context: TimeLineRendererContext) => void;
  updateContext: (height: number, width: number, resolution: number) => void;
  updateValues: (data: BucketTimed<number>[], animate?: boolean) => void;
  updateLayout: () => void;
  destroy: () => Observable<any>;
  isCumulative : ()=> boolean;
  setMaxValue : (value:number)=> void;
  hover : ()=> Observable<ResourceTimedSelected>;
  leave : ()=> Observable<ResourceTimedSelected>;
}


import {
  BucketTimed,
  PointTimed,
  ResourceTimedSelected,
  TimeLineRenderer,
  TimeLineRendererContext
} from 'inugami-ng/models'
import {Observable} from 'rxjs'
import {SVG, SVG_ANIMATION, SVG_BUILDER, SVG_TRANSFORM} from 'inugami-ng/services'
import {signal} from '@angular/core'
import {ObservableSubscriber} from 'inugami-ng/utils'

interface RectElementInfo {
  element: SVGElement;
  index: number;
  targetHeight: number;
}

const NOT_HOVER           = 'not-hover'
const HOVER               = 'hover'
const DATA_TIME           = 'data-date'
const DATA_VALUE          = 'data-value'
const DATA_BUCKET_INDEX   = 'data-bucket-index'
const DATA_RESOURCE_INDEX = 'data-resource-index'
const DATA_VALUE_INDEX    = 'data-value-index'

export class InuSvgTimelineHistogram implements TimeLineRenderer {
  //=============================================
  // ATTRIBUTES
  //=============================================
  graph: SVGElement | undefined;
  height: number | undefined;
  width: number | undefined;
  resolution: number | undefined;
  duration: number            = 500;
  data: BucketTimed<number>[] = [];
  maxValue                    = signal<number | undefined>(undefined);
  nodes: any                  = {};
  hoverObservable             = new ObservableSubscriber<ResourceTimedSelected>();
  leaveObservable             = new ObservableSubscriber<ResourceTimedSelected>();
  hoverData                   = signal<ResourceTimedSelected | undefined>(undefined);
  //=============================================
  // INIT
  //=============================================
  init(context: TimeLineRendererContext): void {
    this.graph      = context.graph;
    this.height     = context.height;
    this.width      = context.width;
    this.resolution = context.resolution;
    if (this.data && this.data.length > 0) {
      this.updateLayout(false);
    }
  }

  setMaxValue(value: number) {
    this.maxValue.set(value);
  }

  updateContext(height: number, width: number, resolution: number): void {
    this.height     = height;
    this.width      = width;
    this.resolution = resolution;
  }

  destroy(): Observable<any> {
    const result = new ObservableSubscriber<any>();

    this.hoverObservable.unsubscribe();
    this.leaveObservable.unsubscribe();

    if (!this.graph || !this.graph.firstChild) {
      result.next({});
      return result.observable();
    }

    const children = Array.from(this.graph.children) as SVGElement[];

    if (children.length === 0) {
      result.next({});
      return result.observable();
    }

    SVG_ANIMATION.animate(
      (progress: number) => {
        const scaleY = 1 - progress;

        for (const child of children) {
          SVG_TRANSFORM.scale(child, 1, scaleY);
        }
      },
      {
        duration: this.duration,
        timer   : SVG_ANIMATION.TYPES.easeOutCubic,
        onDone  : () => {
          result.next({});
        }
      }
    );

    return result.observable();
  }

  updateValues(data: BucketTimed<number>[], animate?: boolean): void {
    this.data = data;
    this.updateLayout(animate);
  }

  hover(): Observable<ResourceTimedSelected> {
    return this.hoverObservable.observable();
  }

  leave(): Observable<ResourceTimedSelected> {
    return this.leaveObservable.observable();
  }

  //=============================================
  // RENDERING WITH SMOOTH DOM ANIMATION
  //=============================================
  updateLayout(animate?: boolean) {
    if (!this.graph) {
      return;
    }

    while (this.graph.firstChild) {
      this.graph.removeChild(this.graph.firstChild);
    }


    const rectInfos: RectElementInfo[] = [];
    const keys                         = Object.keys(this.nodes);
    let bucketIndex                    = 0;
    for (let bucket of this.data) {
      if (!keys.includes(bucket.name)) {
        this.renderBucket(bucket, rectInfos, bucketIndex);
      }
      bucketIndex++;
    }

    if (animate) {
      this.applyFrame(rectInfos, 0);

      SVG_ANIMATION.animate(
        (progress: number) => {
          this.applyFrame(rectInfos, progress);
        },
        {
          duration: this.duration,
          timer   : SVG_ANIMATION.TYPES.easeOutCubic
        }
      );
    } else {
      const res            = this.resolution ?? 100;
      const width          = (this.width ?? 400) / res;
      const stackedOffsets = new Array(res).fill(0);
      for (const item of rectInfos) {
        const currentHeight = item.targetHeight;
        const currentOffset = stackedOffsets[item.index] ?? 0;
        const posY          = -(currentOffset + currentHeight);

        item.element.setAttribute('height', '' + currentHeight);
        SVG.TRANSFORM.matrix(item.element, 1, 1, width * item.index, posY);
        stackedOffsets[item.index] = currentOffset + currentHeight;
      }
    }

  }

  private applyFrame(rectInfos: RectElementInfo[], progress: number) {
    const res            = this.resolution ?? 100;
    const width          = (this.width ?? 400) / res;
    const stackedOffsets = new Array(res).fill(0);

    for (const item of rectInfos) {
      const currentHeight = item.targetHeight * progress;
      const currentOffset = stackedOffsets[item.index] ?? 0;
      const posY          = -(currentOffset + currentHeight);

      item.element.setAttribute('height', '' + currentHeight);
      SVG.TRANSFORM.matrix(item.element, 1, 1, width * item.index, posY);
      stackedOffsets[item.index] = currentOffset + currentHeight;
    }
  }

  private renderBucket(bucket: BucketTimed<number>, rectInfos: RectElementInfo[], bucketIndex: number) {
    if (!this.graph) {
      return;
    }
    const result = SVG_BUILDER.createGroup(this.graph, {
      styleClass: ['bucket',
                   bucket.name,
                   ...bucket.tags ?? []].join(' ')
    });

    this.renderBucketResources(bucket, result, rectInfos, bucketIndex);
  }

  private renderBucketResources(bucket: BucketTimed<number>,
                                result: SVGElement | null,
                                rectInfos: RectElementInfo[],
                                bucketIndex: number) {
    let resourceIndex = 0;
    for (let resource of bucket.resources ?? []) {
      const resultResource = SVG_BUILDER.createGroup(result, {
        styleClass: ['bucket-resource',
                     resource.name].join(' ')
      });
      resultResource?.setAttribute('aria-uri', resource.uri ?? '');

      const values = resource.values ?? [];
      for (let i = 0; i < values.length; i++) {
        this.renderValueNode(values[i], resultResource, i, rectInfos, bucketIndex, resourceIndex);
      }
      resourceIndex++;
    }
  }

  private renderValueNode(value: PointTimed<number>,
                          resultResource: SVGElement | null,
                          index: number,
                          rectInfos: RectElementInfo[],
                          bucketIndex: number,
                          resourceIndex: number) {
    if (!resultResource || !value || value.value === undefined) {
      return;
    }

    const maxValue     = this.maxValue() ?? 1;
    const canvasHeight = this.height ?? 1;
    const ratio        = canvasHeight / maxValue;
    const targetHeight = value.value * ratio;
    const width        = (this.width ?? 400) / (this.resolution ?? 100);

    const result = SVG_BUILDER.createRect(resultResource, {
      styleClass: ['bucket-resource-value'].join(' '),
      height    : 0,
      width     : width
    });

    if (!result) {
      return;
    }

    const timeStamp = value.time instanceof Date ? value.time.getTime() : value.time;
    result.setAttribute(DATA_TIME, '' + timeStamp);
    result.setAttribute(DATA_VALUE, '' + value.value);
    result.setAttribute(DATA_BUCKET_INDEX, '' + bucketIndex);
    result.setAttribute(DATA_RESOURCE_INDEX, '' + resourceIndex);
    result.setAttribute(DATA_VALUE_INDEX, '' + index);
    result.onmouseover  = (event) => this.onHover(event);
    result.onmouseleave = (event) => this.onLeave(event);
    rectInfos.push({
                     element     : result,
                     index       : index,
                     targetHeight: targetHeight
                   });
  }

  public isCumulative() {
    return true;
  }

  private onHover(event: MouseEvent) {
    const currentNode = event.currentTarget as SVGElement;
    SVG_TRANSFORM.addClass(currentNode, HOVER);

    const currentParent = (currentNode.parentNode as SVGElement)?.parentNode as SVGElement;
    const grandParent   = currentParent?.parentNode;
    for (const child of this.graph?.childNodes ?? []) {
      SVG_TRANSFORM.addClass(child as SVGElement, NOT_HOVER);
    }

    if (currentParent) {
      SVG_TRANSFORM.removeClass(currentParent, NOT_HOVER);
      SVG_TRANSFORM.addClass(currentParent, HOVER);
    }

    const bucketIndex   = Number(currentNode.getAttribute(DATA_BUCKET_INDEX));
    const bucket        = this.data[bucketIndex]
    const resourceIndex = Number(currentNode.getAttribute(DATA_RESOURCE_INDEX));
    const resource      = bucket.resources[resourceIndex];
    const valueIndex    = Number(currentNode.getAttribute(DATA_VALUE_INDEX));

    const point = resource.values[valueIndex];

    const currentData: ResourceTimedSelected = {
      event : SVG_BUILDER.buildMouseEvent(event),
      bucket: <BucketTimed<number>>{
        name     : bucket.name,
        tags     : bucket.tags,
        resources: [
          {
            uri   : resource.uri,
            unit  : resource.unit,
            values: [point]
          }
        ]
      },
      point : point
    };
    this.hoverData.set(currentData);
    this.hoverObservable.onNextValue(currentData);
  }

  private onLeave(event: MouseEvent) {

    const hoverData = this.hoverData();
    if (hoverData) {
      this.leaveObservable.onNextValue(hoverData);
    }

    for (const child of this.graph?.childNodes ?? []) {
      if (!child) {
        continue
      }
      SVG_TRANSFORM.removeClass(child as SVGElement, NOT_HOVER);
      SVG_TRANSFORM.removeClass(child as SVGElement, HOVER);
      for (const subChild of child.childNodes ?? []) {
        SVG_TRANSFORM.removeClass(child as SVGElement, NOT_HOVER);
        SVG_TRANSFORM.removeClass(child as SVGElement, HOVER);
      }
    }
    const currentNode = event.currentTarget as SVGElement;
    SVG_TRANSFORM.removeClass(currentNode as SVGElement, NOT_HOVER);
    SVG_TRANSFORM.removeClass(currentNode as SVGElement, HOVER);
  }
}


import {
  CircleOption,
  Dimension, MouseEventData,
  Position,
  RectOption,
  Size,
  SvgAnimationCallback,
  SvgAnimationOption,
  SvgAnimationParameters,
  SvgAnimations,
  SvgAssetDTOOptions,
  SvgAssetElement,
  SvgAssets,
  SvgBuilder,
  SvgDefsPatternOption,
  SvgFilterOption,
  SvgMath,
  SvgOptionalOption,
  SvgStyle,
  SvgStyleGenerators,
  SvgTransform,
  TextOption,
  TransformationInfo,
  Vector
} from "inugami-ng/models";
import {SvgAsset, SvgAssetSet} from 'inugami-svg-assets';
import {SvgAssetUtils} from './svg.asset.utils';


export const DEFAULT_FONT_SIZE = 12;
export const TWO_PI            = 2 * Math.PI;
export const TWO_PI_RATIO      = (2 * Math.PI) / 360;
export const DEGRE_CONVERTOR   = 180 / Math.PI;


const isNull = (value: any): boolean => {
  return value == undefined || value == null;
}

const isNotNull = (value: any): boolean => {
  return value != undefined && value != null;
}

const convertToNumber = (value: any): number | null => {
  return value == undefined || value == null ? null : Number(value);
}

//#############################################################################
// ASSETS
//#############################################################################
const ASSETS: SvgAssetSet[] = [];

export const SVG_ASSETS: SvgAssets = {
  getAssetSets: (): SvgAssetSet[] => {},
  register: (sets: SvgAssetSet[]) => {},
  getAsset: (setName: string, assetName: string): SvgAsset | undefined => {}
}

//#############################################################################
// SVG_CONST
//#############################################################################
export const SVG_CONST: any = {
  DATETIME_YEAR     : 60000 * 1440 * 365,
  MINUTE            : 60000,
  NB_MINUTES_PER_DAY: 1440,
  NANO_TO_MILLIS    : 1000000
};


//#############################################################################
// SVG_MATH
//#############################################################################
export const SVG_MATH: SvgMath = {
  convertToRadian: (angle: number): number => {},

  convertToDegre: (rad: number): number => {},
  rotate: (x: number, y: number, angle: number): Position => {},

  rotateByRef: (xRef: number, yRef: number, x: number, y: number, angle: number): Position => {},

  size: (node: SVGElement | HTMLElement): Size => {},

  computeDimension: (parent: SVGElement | HTMLElement,
                     widthRatio: number | null,
                     heightRatio: number | null,
                     fontRatio: number | null): Dimension => {},

  nowNano: () => {},
  zoom: (value: number, zoom: number) => {}
}


//#############################################################################
// SVG_BUILDER
//#############################################################################
export const SVG_BUILDER: SvgBuilder = {

  createAsset(option: SvgAssetDTOOptions): SvgAssetElement | undefined {},

  // ========================================================================
  // createDefs
  // ========================================================================
  createDefs       : (parent: SVGElement | HTMLElement | null): SVGElement | null => {},
  createFilter     : (parentDefs: SVGElement | HTMLElement | null,
                      id: string,
                      option?: SvgFilterOption): SVGElement | null => {},
  createDefsPattern: (parent: SVGElement | HTMLElement | null,
                      id: string,
                      option?: SvgDefsPatternOption): SVGElement | null => {},
  // ========================================================================
  // createGroup
  // ========================================================================
  createGroup: (parent: SVGElement | HTMLElement | null | undefined, option?: SvgOptionalOption): SVGElement | null => {},

  // ========================================================================
  // createText
  // ========================================================================
  createText: (label: stri},


  // ========================================================================
  // createLine
  // ========================================================================
  createLine: (vector: Vector,
               parent: SVGElement | null | undefined,
               option?: SvgOptionalOption): SVGElement | null => {},
  // ========================================================================
  // createCurve
  // ========================================================================
  ng, parent: SVGElement | null | undefined, option?: SvgOptionalOption): SVGElement | null => {},


  // ========================================================================
  // createLine
  // ========================================================================
  createLine: (vector: Vector,
               parent: SVGElement | null | undefined,
               option?: SvgOptionalOption): SVGElement | null => {},
  // ========================================================================
  // createCurve
  // ========================================================================
  createCurve(parent: SVGElement | null | undefined,
              curve: string,
              option: SvgOptionalOption | undefined): SVGElement | null {},
  // ========================================================================
  // createLine
  // ========================================================================
  createRect: (parent: SVGElement|null|undefined, option?: RectOption): SVGElement | null => {},


  // ========================================================================
  // Circle
  // ========================================================================
  createCircle: (parent: SVGElement|null|undefined, option?: CircleOption): SVGElement | null => {},
  ellipse: (parent: SVGElement|null|undefined, option?: CircleOption): SVGElement | null => {},


  // ========================================================================
  // TEXT
  // ========================================================================
  text: (parent: SVGElement|null|undefined, label: string, option?: TextOption): SVGElement | null => {},

  // ========================================================================
  // USE
  // ========================================================================
  createUse(id: string,
            parent: SVGElement | HTMLElement | null,
            option: SvgOptionalOption | undefined): SVGElement | null {},
  // ========================================================================
  // createGroup
  // ========================================================================
  createNode: (nodeType: string,
               parent: SVGElement | HTMLElement | null | undefined,
               option?: SvgOptionalOption): SVGElement | null => {},

  buildMouseEvent : (event:MouseEvent) : MouseEventData => {}
}


//#############################################################################
// SVG_TRANSFORMATION
//#############################################################################
export const SVG_TRANSFORM: SvgTransform = {

  clean: (node: SVGElement) => {},

  // ========================================================================
  // translate
  // ========================================================================
  translateX: (node: SVGElement | null, posX: number): void => {},
  translateY: (node: SVGElement | null, posY: number): void => {},


  // ========================================================================
  // SCALE
  // ========================================================================
  scale : (node: SVGElement, scaleX: number, scaleY: number) => {},
  scaleX: (node: SVGElement, scaleX: number) => {},
  scaleY: (node: SVGElement, scaleY: number) => {},


  // ========================================================================
  // MATRIX
  // ========================================================================
  matrix: (node: SVGElement, scaleX: number, scaleY: number, posX: number, posY: number) => {},

  // ========================================================================
  // extractTransformInformation
  // ========================================================================
  extractTransformInformation: (node: SVGElement | HTMLElement): TransformationInfo => {},

  // ========================================================================
  // ALIGN
  // ========================================================================
  center    : (compo: SVGElement | null,
               svgContainer: SVGElement | HTMLElement | null,
               onX: boolean,
               onY: boolean): number => {},
  centerOnly: (compo: SVGElement | null,
               svgContainer: SVGElement | HTMLElement | null,
               onX: boolean,
               onY: boolean): void => {},

  // ========================================================================
  // TOOLS
  // ========================================================================
  toogleClass: (node: SVGElement | HTMLElement | null | undefined, styleclass: string): void => {},
  removeClass: (node: SVGElement | HTMLElement | null | undefined, styleclass: string): void => {},
  addClass   : (node: SVGElement | HTMLElement | null | undefined, styleclass: string): void => {},
  hasClass   : (node: SVGElement | HTMLElement | null | undefined, styleclass: string): boolean => {}
};

//#############################################################################
// SVG STYLE GENERATOR
//#############################################################################
export const SVG_STYLE_GENERATOR: SvgStyleGenerators = {
  BY_TYPE: (value: number, maxValue: number, minValue: number, type: string): SvgStyle => {}
}

//#############################################################################
// SVG ANIMATION
//#############################################################################
export const SVG_ANIMATION: SvgAnimations = {
  TYPES  : {
    linear      : (time: number): number => time,
    parabolic   : (time: number): number => -(4 * Math.pow(time, 2)) + (4 * time),
    easeOutCubic: (time: number) => Math.pow(time - 1, 3) + 1,
    easeInCubic : (time: number) => Math.pow(time, 3),
    easeInQuad  : (time: number) => time * time,
    easeOutQuad : (time: number) => time * (2 - time),
  },
  animate: (callback: SvgAnimationCallback, option?: SvgAnimationOption): void => {}
}

class AnimationHandler {
  private animeId: number | null = null;
  constructor(private parameters: SvgAnimationParameters) {}
  public run() {}
}

//#############################################################################
// SVG_TRANSFORMATION
//#############################################################################
export const SVG = {
  CONSTANTS: SVG_CONST,
  MATH     : SVG_MATH,
  BUILDER  : SVG_BUILDER,
  TRANSFORM: SVG_TRANSFORM,
  STYLE    : SVG_STYLE_GENERATOR,
  ANIMATION: SVG_ANIMATION
}



export interface SvgOptionalOption{
  styleClass?: string|null
}

export interface SvgDefsPatternOption{
  x?: number;
  y?: number;
  width?: number;
  height?: number;
  patternUnits?: 'userSpaceOnUse'|'objectBoundingBox';
}
export interface SvgFilterOption{
  x?: number;
  y?: number;
  width?: number;
  height?: number;
  style?: string;
}

export interface RectOption extends SvgOptionalOption{
  height?: number;
  width?: number;
  round?: number;
}

export interface CircleOption extends SvgOptionalOption{
  height?: number;
  width?:number;
  round?: number;
  x?:number;
  y?:number;
}

export interface TextOption extends SvgOptionalOption{
  fontSize?: number;
}

export type SvgAnimationDone = ()=> void;
export type SvgAnimationCallback = (time:number)=> void;
export type SvgTimerGenerator = (time:number)=>number;

export interface SvgAnimationOption {
  timer?:SvgTimerGenerator;
  delay?: number;
  duration?:number;
  onDone?:SvgAnimationDone;
}

export interface SvgAnimationParameters {
  timer:SvgTimerGenerator;
  delay: number;
  duration:number;
  startTime:number,
  ttl:number;
  callback:SvgAnimationCallback;
  onDone?:SvgAnimationDone;
}


import {
  InuSvgTimeline,
  InuSvgTimelineHistogram,
  InuSvgTimelineLine
} from 'inugami-ng/components/inu-svg-timeline';

import {
  BucketTimed,
  BucketTimedLoader,
  InuSelectItem,
  ResourceTimedSelected,
  TimeLineRenderer
} from 'inugami-ng/models'

import {FieldTree, form, FormField, required} from '@angular/forms/signals'

@Component({
   templateUrl: './inu-svg-timeline.view.html',
   styleUrls  : ['./inu-svg-timeline.view.scss'],
   imports    : [
     InuSvgTimeline,
     FormField
   ]
})
export class MyView {
  timeModel = signal<TimeForm>({
                                dates: [new Date('2026-08-06T00:00:00.000+02:00'),
                                        new Date('2026-08-06T23:59:00.000+02:00')]
                              });

  currentTimeForm: FieldTree<TimeForm> = form(this.timeModel, (path) => {
    required(path.dates);
  });
}
